 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('ipt_dupChkYn').getValue() !== 'Y' && !$('#dupBtn').hasClass("bt2")) {
        await $c.win.alert("단위조항 중복확인 후 저장이 가능합니다.");
        return;
    }
    let sprtRoomNo = $('#slc_junmoon option:selected').val();
    if (sprtRoomNo.length == 0) {
        await $c.win.alert("법규전문을 선택해 주시기 바랍니다.");
        return;
    }
    if (!await $c.win.confirm("저장하시겠습니까?")) {
        return;
    }
    sprtRoomNo = sprtRoomNo.split("_")[0];
    $c.util.getComponent('ipt_sprtRoomNo').setValue(sprtRoomNo);
    $c.util.getComponent('ipt_updateYn').setValue("Y");
    $c.util.getComponent('ipt_relLawDtlContn').setValue(DEXT5.getBodyValue("dext5editor1"));
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeText
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeText = function () {
    /* sdd-asis-lifecycle:begin fn_changeText — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_dupChkYn').setValue("N");
    setBtnEnable($('#dupBtn'));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
